package com.yeyamo_mobile.api.referral_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity@Table(name="referral_history")public class ReferralHistoryEntity{@Id private UUID id;@Column(name="attribution_id")private UUID attributionId;@Column(name="actor_user_id",length=120)private String actorUserId;@Column(nullable=false,length=80)private String action;@Column(nullable=false,columnDefinition="TEXT")private String details;@Column(name="occurred_at",nullable=false)private Instant occurredAt;protected ReferralHistoryEntity(){}public ReferralHistoryEntity(UUID attribution,String actor,String action,String details){id=UUID.randomUUID();attributionId=attribution;actorUserId=actor;this.action=action;this.details=details;occurredAt=Instant.now();}public UUID getId(){return id;}public UUID getAttributionId(){return attributionId;}public String getAction(){return action;}public String getDetails(){return details;}public Instant getOccurredAt(){return occurredAt;}}
